-- The phash algorithm now samples fewer frames from videos of 2.5 minutes or
-- less, so the phashes stored for those files were generated by a different
-- algorithm and are no longer comparable. Remove them so that they are
-- regenerated by the next generate task.
--
-- Files with an unknown (zero) duration are left alone, since the algorithm
-- treats those as full length.
DELETE FROM `files_fingerprints`
WHERE `type` = 'phash'
  AND `file_id` IN (
    SELECT `file_id`
    FROM `video_files`
    WHERE `duration` > 0
      AND `duration` <= 150
  );
